'use strict';
function videoSpeed(o){return o.speed||1}
function cropRect(o){const crop=o.crop||{x:0,y:0,w:1,h:1};return{x:crop.x,y:crop.y,w:crop.w,h:crop.h}}
function mediaMask(c,o,w,h){if(!o.mask||o.mask==='none')return;c.beginPath();if(o.mask==='circle')c.ellipse(0,0,w/2,h/2,0,0,Math.PI*2);else if(o.mask==='rounded')c.roundRect(-w/2,-h/2,w,h,Math.min(w,h)*.15);else{c.moveTo(0,-h/2);c.lineTo(w/2,0);c.lineTo(0,h/2);c.lineTo(-w/2,0);c.closePath()}c.clip()}
drawVideoObject=function(c,o,v){const video=videoFor(o);if(video.readyState<2)return;const crop=cropRect(o),w=o.width*crop.w,h=o.height*crop.h;c.save();c.translate(v.x,v.y);c.rotate(v.rotation*Math.PI/180);c.scale(v.scale,v.scale);c.globalAlpha=v.opacity;mediaMask(c,o,w,h);c.drawImage(video,video.videoWidth*crop.x,video.videoHeight*crop.y,video.videoWidth*crop.w,video.videoHeight*crop.h,-w/2,-h/2,w,h);c.restore()};
const imagePropBeforeCrop=prop;prop=function(c,o,v){if(o.type!=='image')return imagePropBeforeCrop(c,o,v);const image=loadImage(o.src);if(!image.complete||!image.naturalWidth)return;const crop=cropRect(o),w=160*crop.w,h=160*image.naturalHeight/image.naturalWidth*crop.h;c.save();c.translate(v.x,v.y);c.rotate(v.rotation*Math.PI/180);c.scale(v.scale,v.scale);c.globalAlpha=v.opacity;mediaMask(c,o,w,h);c.drawImage(image,image.naturalWidth*crop.x,image.naturalHeight*crop.y,image.naturalWidth*crop.w,image.naturalHeight*crop.h,-w/2,-h/2,w,h);c.restore()};
const originalMediaBounds=bounds;bounds=function(o,v){if(o.type==='video'){const crop=cropRect(o),w=o.width*crop.w*v.scale,h=o.height*crop.h*v.scale;return{x:v.x-w/2,y:v.y-h/2,w,h}}if(o.type==='image'){const image=images.get(o.src);if(image?.naturalWidth){const crop=cropRect(o),w=160*crop.w*v.scale,h=160*image.naturalHeight/image.naturalWidth*crop.h*v.scale;return{x:v.x-w/2,y:v.y-h/2,w,h}}}return originalMediaBounds(o,v)};
function setVideoSpeed(o,speed){if(o.locked)return;stop();const old=videoSpeed(o),start=clipStart(o),span=clipEnd(o)-start,sourceSpan=span*old,newSpan=Math.min(sourceSpan/speed,60-start);o.speed=speed;o.out=start+newSpan;current().duration=Math.max(current().duration,o.out);for(const key of o.keys)if(key.t>=start&&key.t<=start+span)key.t=start+(key.t-start)*newSpan/span;save();render()}
syncVideoMedia=function(){const active=new Set();for(const o of current().objects.filter(o=>o.type==='video')){const video=videoFor(o);if(!visibleAt(o,time)||video.readyState<2){video.pause();continue}active.add(o.id);const desired=clamp(o.sourceOffset+(time-clipStart(o))*videoSpeed(o),0,Math.max(0,o.sourceDuration-.001));video.playbackRate=videoSpeed(o);if(!video.seeking&&Math.abs(video.currentTime-desired)>((playing||recording)&&!video.paused?.15:.015))video.currentTime=desired;if((playing||recording)&&desired<o.sourceDuration-.02){if(video.paused&&!video.seeking)video.play().catch(()=>{})}else video.pause()}for(const [id,entry] of videoMedia)if(!active.has(id))entry.video.pause()};
normalizeLinkedMedia=function(){const videos=new Map();let offset=0;for(const s of project.scenes){for(const o of s.objects)if(o.type==='video')videos.set(o.id,{o,s,offset});offset+=s.duration}project.audioClips=tracks().filter(c=>!c.videoId||videos.has(c.videoId));for(const c of tracks()){if(!c.videoId)continue;const {o,s,offset}=videos.get(c.videoId);c.rate=videoSpeed(o);c.start=offset+clipStart(o);c.offset=o.sourceOffset;c.duration=Math.min(clipEnd(o,s)-clipStart(o),(c.sourceDuration-c.offset)/c.rate);const f=fadeDurations(c);c.fadeIn=f.in;c.fadeOut=f.out}};
syncLinkedAudio=function(o){normalizeLinkedMedia()};
const visualMoveWithMedia=moveVisual;moveVisual=function(o,change){if(o.locked)return;if(o.type!=='video')return visualMoveWithMedia(o,change);const start=clipStart(o),end=clipEnd(o),speed=videoSpeed(o);if(change.mode==='left'){const next=clamp(start+change.delta,Math.max(0,start-o.sourceOffset/speed),end-.1);o.sourceOffset+=(next-start)*speed;o.in=next}else if(change.mode==='right')o.out=clamp(end+change.delta,start+.1,Math.min(current().duration,start+(o.sourceDuration-o.sourceOffset)/speed));else visualMoveWithMedia(o,change);syncLinkedAudio(o)};
async function freezeFrame(o){if(o.locked)return;stop();const v=videoFor(o),desired=clamp(o.sourceOffset+(time-clipStart(o))*videoSpeed(o),0,o.sourceDuration-.01);await seekVideo(v,desired);const crop=cropRect(o),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(v.videoWidth*crop.w));canvas.height=Math.max(1,Math.round(v.videoHeight*crop.h));canvas.getContext('2d').drawImage(v,v.videoWidth*crop.x,v.videoHeight*crop.y,v.videoWidth*crop.w,v.videoHeight*crop.h,0,0,canvas.width,canvas.height);const state=stateAt(o,time),at=clamp(time,0,current().duration-.1);const image=newObject('image',{name:'Freeze · '+o.name,src:canvas.toDataURL('image/png'),in:at,out:Math.min(current().duration,Math.max(at+.1,clipEnd(o))),mask:o.mask||'none',...(o.chromaKey?{chromaKey:structuredClone(o.chromaKey)}:{})});image.keys=[{t:at,v:{...state,scale:state.scale*o.width*crop.w/160}}];save();render()}
let mediaProcessing=false;
async function reverseVideo(o){if(o.locked||mediaProcessing)return;stop();mediaProcessing=true;window.editorTaskBusy=true;const target=project;try{$('studioTaskStatus').textContent='Reversing footage…';const input=await(await fetch(o.src)).arrayBuffer(),span=(clipEnd(o)-clipStart(o))*videoSpeed(o);const response=await fetch('/api/reverse?start='+o.sourceOffset+'&duration='+span,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:input});if(!response.ok){const error=await response.json();throw Error(error.error||'Reverse is unavailable.')}const blob=await response.blob(),src=await dataURL(blob),video=document.createElement('video');video.muted=true;video.src=src;await mediaReady(video);if(project!==target)throw Error('Project changed while reversing. Try again.');o.src=src;o.sourceDuration=video.duration;o.sourceOffset=0;o.out=Math.min(clipEnd(o),clipStart(o)+video.duration/videoSpeed(o));o.reversed=!o.reversed;videoMedia.set(o.id,{src,video});for(const c of tracks().filter(c=>c.videoId===o.id)){try{const buffer=await decodeFile(blob);c.src=src;c.sourceDuration=buffer.duration;c.offset=0;delete c.normalization;delete c.beats;delete c.words;delete c.mouthCues;audioBuffers.set(c.id,buffer)}catch{delete c.videoId}}save();render();toast('Video and linked audio reversed.')}catch(e){toast(e.message)}finally{mediaProcessing=false;window.editorTaskBusy=false;$('studioTaskStatus').textContent=''}}
const advancedMediaControls=renderControls;renderControls=function(){advancedMediaControls();const o=object();if(!o||!['video','image'].includes(o.type))return;const panel=document.createElement('details');panel.open=true;panel.innerHTML='<summary>Crop & mask</summary><label>Mask<select id="mediaMask"><option value="none">None</option><option value="circle">Ellipse</option><option value="rounded">Rounded rectangle</option><option value="diamond">Diamond</option></select></label>'+['x','y','w','h'].map(k=>'<label>Crop '+({x:'left',y:'top',w:'width',h:'height'}[k])+' %<input data-crop="'+k+'" type="number" min="0" max="100" step="1"></label>').join('')+'<button id="resetCrop">Reset crop</button>';
 if(o.type==='video')panel.insertAdjacentHTML('afterbegin','<label>Speed<select id="videoSpeed"><option value="0.25">0.25×</option><option value="0.5">0.5×</option><option value="1">1×</option><option value="1.5">1.5×</option><option value="2">2×</option><option value="4">4×</option></select></label><div class="posegrid"><button id="freezeFrame">Freeze frame</button><button id="reverseVideo">'+(o.reversed?'Reverse again':'Reverse footage')+'</button></div>');$('controls').prepend(panel);$('mediaMask').value=o.mask||'none';$('mediaMask').onchange=e=>{o.mask=e.target.value;save();draw()};const crop=cropRect(o);panel.querySelectorAll('[data-crop]').forEach(input=>{const key=input.dataset.crop;input.value=Math.round(crop[key]*100);input.onchange=()=>{o.crop??={...crop};const value=clamp(+input.value/100,key==='w'||key==='h'?.05:0,1);if(key==='x')o.crop.x=Math.min(value,1-o.crop.w);if(key==='y')o.crop.y=Math.min(value,1-o.crop.h);if(key==='w')o.crop.w=Math.min(value,1-o.crop.x);if(key==='h')o.crop.h=Math.min(value,1-o.crop.y);save();render()}});$('resetCrop').onclick=()=>{delete o.crop;save();render()};if(o.type==='video'){$('videoSpeed').value=videoSpeed(o);$('videoSpeed').onchange=e=>setVideoSpeed(o,+e.target.value);$('freezeFrame').onclick=()=>freezeFrame(o).catch(e=>toast(e.message));$('reverseVideo').onclick=()=>reverseVideo(o);$('videoSource').max=Math.max(0,o.sourceDuration-(clipEnd(o)-clipStart(o))*videoSpeed(o));$('videoSource').onchange=e=>{o.sourceOffset=clamp(+e.target.value||0,0,Math.max(0,o.sourceDuration-(clipEnd(o)-clipStart(o))*videoSpeed(o)));syncLinkedAudio(o);save();draw()};for(const [id,fit] of [['fitVideo',Math.min],['fillVideo',Math.max]])$(id).onclick=()=>{const c=cropRect(o);setKey(o,{...stateAt(o,time),x:480,y:270,scale:fit(960/(o.width*c.w),540/(o.height*c.h))});render()}}panel.querySelectorAll('input,select,button').forEach(e=>e.disabled=!!o.locked)};
const editingValidator=valid;valid=function(p){return editingValidator(p)&&p.scenes.every(s=>s.objects.every(o=>(o.speed===undefined||Number.isFinite(o.speed)&&o.speed>=.25&&o.speed<=4)&&(!o.crop||['x','y','w','h'].every(k=>Number.isFinite(o.crop[k]))&&o.crop.x>=0&&o.crop.y>=0&&o.crop.w>=.05&&o.crop.h>=.05&&o.crop.x+o.crop.w<=1.0001&&o.crop.y+o.crop.h<=1.0001)&&(!o.mask||['none','circle','rounded','diamond'].includes(o.mask))&&(o.type!=='video'||o.sourceOffset+((o.out??s.duration)-(o.in??0))*videoSpeed(o)<=o.sourceDuration+.05)))};
